{

    internal InnerInferenceComponentInferenceComponentContainerSpecificationFactory ContainerFactory { get; set; }

    internal InnerInferenceComponentInferenceComponentDataCacheConfigFactory DataCacheConfigFactory { get; set; }

    internal InnerInferenceComponentInferenceComponentComputeResourceRequirementsFactory ComputeResourceRequirementsFactory { get; set; }

    internal InnerInferenceComponentInferenceComponentDataCacheConfigFactory CurrentDataCacheConfigFactory { get; set; }

    internal InnerInferenceComponentInferenceComponentSchedulingConfigFactory SchedulingConfigFactory { get; set; }

    internal InnerInferenceComponentInferenceComponentStartupParametersFactory StartupParametersFactory { get; set; }

    protected override Humidifier.SageMaker.InferenceComponentTypes.InferenceComponentSpecification Create()
    {
        var inferenceComponentSpecificationResult = CreateInferenceComponentSpecification();
        factoryAction?.Invoke(inferenceComponentSpecificationResult);

        return inferenceComponentSpecificationResult;
    }

    private Humidifier.SageMaker.InferenceComponentTypes.InferenceComponentSpecification CreateInferenceComponentSpecification()
    {
        var inferenceComponentSpecificationResult = new Humidifier.SageMaker.InferenceComponentTypes.InferenceComponentSpecification();

        return inferenceComponentSpecificationResult;
    }
    public override void CreateChildren(Humidifier.SageMaker.InferenceComponentTypes.InferenceComponentSpecification result)
    {
        base.CreateChildren(result);

        result.Container ??= ContainerFactory?.Build();
        result.DataCacheConfig ??= DataCacheConfigFactory?.Build();
        result.ComputeResourceRequirements ??= ComputeResourceRequirementsFactory?.Build();
        result.CurrentDataCacheConfig ??= CurrentDataCacheConfigFactory?.Build();
        result.SchedulingConfig ??= SchedulingConfigFactory?.Build();
        result.StartupParameters ??= StartupParametersFactory?.Build();
    }

} // End Of Class

